[metadata] {"filePath": "/workspace/repo/pacquet/crates/resolving-deps-resolver/src/resolve_dependency_tree.rs", "oldString": "/// Replace `catalog:` bare specifiers on direct dependencies with the
/// version recorded in the catalogs map. Non-`catalog:` specifiers
/// pass through unchanged.", "newString": "/// Compute the `pkgIdWithPatchHash` for a resolved package: the plain
/// resolution id, plus a `(patch_hash=<hash>)` suffix when a configured
/// `patchedDependencies` entry matches the package's `name@version`.
///
/// Mirrors upstream's per-resolve patch step at
/// [`resolveDependencies.ts:1503-1507`](https://github.com/pnpm/pnpm/blob/097983fbca/installing/deps-resolver/src/resolveDependencies.ts#L1503-L1507).
/// The matched key is recorded in `ctx.applied_patches`. Match
/// precedence (exact → unique range → wildcard) and the
/// two-ranges-conflict error live in
/// [`pacquet_patching::get_patch_info`]; an ambiguous match surfaces as
/// [`ResolveDependencyTreeError::PatchKeyConflict`].
///
/// Patching keys off the resolver's `name_ver`; resolvers that leave it
/// `None` (git / tarball / local) can't be matched by `name@version`
/// and pass through unpatched.
async fn apply_patch_hash(
    ctx: &TreeCtx,
    result: &pacquet_resolving_resolver_base::ResolveResult,
) -> Result<String, ResolveDependencyTreeError> {
    let id = result.id.to_string();
    let Some(patched) = ctx.patched_dependencies.as_deref() else {
        return Ok(id);
    };
    let Some(name_ver) = result.name_ver.as_ref() else {
        return Ok(id);
    };
    let name = name_ver.name.to_string();
    let version = name_ver.suffix.to_string();
    match get_patch_info(Some(patched), &name, &version)
        .map_err(ResolveDependencyTreeError::PatchKeyConflict)?
    {
        Some(patch) => {
            ctx.applied_patches.lock().await.insert(patch.key.clone());
            Ok(format!("{id}(patch_hash={})", patch.hash))
        }
        None => Ok(id),
    }
}

